"""The demo's briefs: generated by the builders at seed time, every number checks out, and nothing writes.

``create_demo --ledger`` stores one pre- and one post-market brief of the last trading day before the demo
is made. In demo mode the pages read them; start-up writes nothing and generating is refused.
"""
import asyncio
import hashlib
import sys
from datetime import date
from pathlib import Path

import pytest

from core.market.calendar import SHANGHAI
from core.market.runtime import set_market_runtime
from core.routines import briefs
from tests.brief_support import Context, by_label, facts, shanghai, walk

TODAY = date(2026, 11, 17)
DAY = '2026-11-16'     # the last trading day before TODAY
SESSIONS = {'SHA:DEMO': DAY, 'NASDAQ:DEMO': '2026-11-13'}
needs_backend = pytest.mark.skipif(sys.version_info < (3, 10), reason='backend.main needs Python 3.10+')


def fingerprint(directory):
    return {str(path.relative_to(directory)): hashlib.sha256(path.read_bytes()).hexdigest()
            for path in sorted(Path(directory).rglob('*')) if path.is_file()}


@pytest.fixture
def demo(tmp_path, monkeypatch):
    from create_demo import create_demo
    directory = tmp_path / 'portfolio'
    create_demo(directory, ledger=True, today=TODAY)
    monkeypatch.setenv('PORTFOLIO_DIR', str(directory))
    monkeypatch.setenv('TRACKER_DEMO_MODE', '1')
    monkeypatch.delenv('TRACKER_QUOTE_SOURCE', raising=False)
    set_market_runtime(None)
    yield directory
    set_market_runtime(None)


def test_the_seeded_briefs_are_what_the_builders_compute_from_the_demo(demo):
    pre, post = briefs.load('premarket', DAY), briefs.load('postmarket', DAY)
    assert (pre['generated_at'], post['generated_at']) == ('2026-11-16T08:45:00+08:00', '2026-11-16T15:45:00+08:00')
    assert briefs.latest_date() == DAY and pre['commentary'] is None and post['commentary'] is None
    counts = walk(pre, Context(directory=demo, trading_date=DAY, now=shanghai('2026-11-16 08:45')))
    assert counts['distance_pct'] == 2 and counts['recent_alert_count'] == 1 and counts['alert_value'] >= 1
    counts = walk(post, Context(directory=demo, trading_date=DAY, now=shanghai('2026-11-16 15:45'), sessions=SESSIONS))
    assert counts['day_pnl_cny'] == 2 and counts['day_pnl_total'] == 1
    # The demo does not go on the internet, and says so.
    news = next(part for part in pre['sections'] if part['id'] == 'news')
    assert news['status'] == {'code': 'not_queried', 'reason': '数据源不可用：演示模式不联网查询公告与新闻'}
    # The demo has several accounts: a level row names the account of the holding it is about.
    stops = [item for item in facts(pre, 'levels') if item['label'].startswith('示例宽基') and item['label'].endswith('止损 54.00')]
    assert stops and all(item['ref']['plan_id'] == 2 and item['ref']['account'] in item['label'] for item in stops)
    assert by_label(post, 'trades')['今日成交']['value'] == 0
    assert all(item['value'] is None for item in facts(pre, 'overnight'))   # the demo script has no index quotes


@needs_backend
def test_demo_pages_read_the_briefs_and_generation_is_refused(demo, tmp_path, monkeypatch):
    monkeypatch.chdir(tmp_path)
    from fastapi.testclient import TestClient
    from backend.main import app
    before = fingerprint(demo)
    client = TestClient(app, base_url='http://127.0.0.1')
    body = client.get('/api/briefs', params={'date': DAY}).json()
    assert body['mode'] == 'demo' and body['latest_date'] == DAY
    for kind in briefs.KINDS:
        item = body['items'][kind]
        assert (item['state'], item['state_text'], item['can_run']) == ('demo', '演示数据', False)
        assert item['run_refusal'] == '演示模式只读，不能生成简报。' and item['brief']['trading_date'] == DAY
    response = client.post('/api/routines/premarket/run')
    assert response.status_code == 403 and response.json() == {'detail': 'Demo mode is read-only'}
    status = client.get('/api/routines/status').json()
    assert status['scheduler']['note'].startswith('演示模式：例行任务不运行')
    assert fingerprint(demo) == before


@needs_backend
def test_demo_start_up_writes_nothing(demo, monkeypatch):
    from fastapi import FastAPI
    from backend import features
    from core.routines import scheduler
    from tests.fakes import FakeClock
    monkeypatch.setattr(scheduler, 'wall_clock', FakeClock('2026-11-17 16:00'))   # every kind is due
    before = fingerprint(demo)

    async def start_up():
        async with features.background(FastAPI()):
            await asyncio.sleep(0.3)

    asyncio.run(start_up())
    assert scheduler.current() is None and scheduler.runs() == []
    assert fingerprint(demo) == before
